/**
 * Per-session usage and cost report for `agent-sdk session get <id> --view cost` and `agent-sdk session list --view cost`.
 *
 * Token usage is a pure fold over the session's `turn.completed` events.
 * Dollars are priced for the whole session by `GET /v1/session/:id/cost`;
 * turns are never priced on their own.
 */
import { CLI_COMMAND_NAME } from "./distribution.js";
import { formatCostUsd } from "./trajectory.js";
export function emptySessionUsageTotals() {
    return {
        turns: 0,
        turnFailures: 0,
        inputTokens: 0,
        outputTokens: 0,
        cacheReadTokens: 0,
        cacheWriteTokens: 0,
    };
}
export function addSessionUsageTotals(target, delta) {
    target.turns += delta.turns;
    target.turnFailures += delta.turnFailures;
    target.inputTokens += delta.inputTokens;
    target.outputTokens += delta.outputTokens;
    target.cacheReadTokens += delta.cacheReadTokens;
    target.cacheWriteTokens += delta.cacheWriteTokens;
}
/** Fold a session event stream into per-turn and total token usage. */
export function buildSessionCostReport(events, cost) {
    let sessionId = "";
    const turns = [];
    const totals = emptySessionUsageTotals();
    for (const event of events) {
        if (sessionId === "" && typeof event.sessionId === "string") {
            sessionId = event.sessionId;
        }
        if (event.type !== "turn.completed" && event.type !== "turn.failed") {
            continue;
        }
        const turn = {
            turnId: event.turnId ?? `turn_${turns.length + 1}`,
            failed: event.type === "turn.failed",
        };
        totals.turns += 1;
        if (event.type === "turn.failed") {
            totals.turnFailures += 1;
            turns.push(turn);
            continue;
        }
        const usage = event.data.usage;
        if (usage !== undefined) {
            turn.usage = usage;
            totals.inputTokens += usage.inputTokens;
            totals.outputTokens += usage.outputTokens;
            totals.cacheReadTokens += usage.cacheReadTokens;
            totals.cacheWriteTokens += usage.cacheWriteTokens;
        }
        turns.push(turn);
    }
    const report = { sessionId, turns, totals };
    if (cost !== undefined && cost.source !== "unavailable") {
        report.cost = cost;
    }
    return report;
}
function formatCount(value) {
    return String(value);
}
function formatSessionCost(cost) {
    if (cost === undefined) {
        return "unavailable";
    }
    const model = cost.model === undefined ? "" : `, ${cost.model}`;
    return `${formatCostUsd(cost.costUsd)} (${cost.source}${model})`;
}
/** Per-turn token table plus the session cost for `agent-sdk session get <sessionId> --view cost`. */
export function formatSessionCostText(report) {
    const lines = [];
    lines.push(`session ${report.sessionId || "(unknown)"}  cost: ${formatSessionCost(report.cost)}`);
    if (report.turns.length === 0) {
        lines.push("No turns recorded.");
        return `${lines.join("\n")}\n`;
    }
    const header = ["TURN", "IN", "OUT", "CACHE R", "CACHE W", "STATUS"];
    const rows = report.turns.map((turn) => [
        turn.turnId,
        turn.usage === undefined ? "—" : formatCount(turn.usage.inputTokens),
        turn.usage === undefined ? "—" : formatCount(turn.usage.outputTokens),
        turn.usage === undefined ? "—" : formatCount(turn.usage.cacheReadTokens),
        turn.usage === undefined ? "—" : formatCount(turn.usage.cacheWriteTokens),
        turn.failed ? "failed" : "ok",
    ]);
    rows.push([
        "total",
        formatCount(report.totals.inputTokens),
        formatCount(report.totals.outputTokens),
        formatCount(report.totals.cacheReadTokens),
        formatCount(report.totals.cacheWriteTokens),
        report.totals.turnFailures > 0 ? `${report.totals.turnFailures} failed` : "",
    ]);
    lines.push(renderTable(header, rows));
    return `${lines.join("\n")}\n`;
}
/**
 * All-sessions token table for `agent-sdk session list --view cost`. Pricing every
 * session would run one billed lookup per session, so dollars are left to
 * `agent-sdk session get <sessionId> --view cost`.
 */
export function formatSessionsCostText(rows) {
    if (rows.length === 0) {
        return "No sessions.\n";
    }
    const header = ["SESSION", "CHANNEL", "TURNS", "IN", "OUT", "UPDATED"];
    const totals = emptySessionUsageTotals();
    const body = rows.map((row) => {
        addSessionUsageTotals(totals, row.totals);
        return [
            row.sessionId,
            row.channelId,
            formatCount(row.totals.turns),
            formatCount(row.totals.inputTokens),
            formatCount(row.totals.outputTokens),
            row.updatedAt ?? "",
        ];
    });
    body.push([
        "total",
        "",
        formatCount(totals.turns),
        formatCount(totals.inputTokens),
        formatCount(totals.outputTokens),
        "",
    ]);
    const lines = [
        renderTable(header, body),
        `Run \`${CLI_COMMAND_NAME} session get <sessionId> --view cost\` for a session's cost.`,
    ];
    return `${lines.join("\n")}\n`;
}
function renderTable(header, rows) {
    const widths = header.map((h, i) => Math.max(h.length, ...rows.map((row) => (row[i] ?? "").length)));
    const renderRow = (row) => row
        .map((cell, i) => cell.padEnd(widths[i] ?? 0))
        .join("  ")
        .trimEnd();
    return [renderRow(header), ...rows.map(renderRow)].join("\n");
}
